-- Etap 8: zdjęcia produktów — z R2 (wgrane w panelu) albo z adresu URL (np. Pexels).
-- src = adres, pod którym przeglądarka pobiera zdjęcie; r2_key = klucz w R2 (pusty dla zdjęć z zewnątrz).
ALTER TABLE product_images ADD COLUMN src TEXT;
CREATE INDEX IF NOT EXISTS idx_product_images ON product_images(product_id, sort);

